<style>
*{box-sizing:border-box}
:root{--bg:#0f1419;--panel:#171e26;--panel2:#1e2833;--line:#2a3644;--text:#e8eef4;--muted:#8a9ba8;--accent:#f59e0b;--accent2:#ef4444;--green:#22c55e;--brick:#c0563b}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--text);overflow-x:hidden}
header{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;background:#0c1116;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}
.brand{display:flex;align-items:center;gap:12px}
.logo{width:36px;height:36px;border-radius:9px;background:linear-gradient(135deg,#f59e0b,#ef4444);display:grid;place-items:center;font-weight:900;font-size:18px;color:white;box-shadow:0 6px 18px rgba(245,158,11,.3)}
.brand h1{font-size:17px;margin:0;letter-spacing:.2px;line-height:1}
.brand p{margin:3px 0 0;font-size:11px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}
.badge{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:#fbbf24;border:1px solid #3a2f14;background:#221a08;padding:7px 10px;border-radius:999px;font-weight:700}
.layout{display:grid;grid-template-columns:300px 1fr;min-height:calc(100vh - 58px)}
@media(max-width:860px){.layout{grid-template-columns:1fr}aside{order:2}}
aside{background:var(--panel);border-right:1px solid var(--line);padding:16px;display:flex;flex-direction:column;gap:16px}
.card{background:var(--panel2);border:1px solid var(--line);border-radius:14px;padding:14px}
.card h2{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin:0 0 12px}
.btns{display:grid;grid-template-columns:1fr 1fr;gap:10px}
button{border:0;cursor:pointer;font-weight:800;border-radius:11px;padding:13px 10px;font-size:14px;transition:.15s}
button:active{transform:scale(.98)}
#testBtn{background:linear-gradient(135deg,#f59e0b,#ef4444);color:white;box-shadow:0 8px 20px rgba(239,68,68,.25);grid-column:span 1}
#resetBtn{background:#2a3644;color:var(--text);border:1px solid #3a4a5e}
#testBtn:hover{filter:brightness(1.07)}
.control{margin:13px 0}
.control:first-child{margin-top:2px}
.control label{display:flex;justify-content:space-between;font-size:13px;margin-bottom:7px;color:#cbd5e1}
.control label b{color:white;background:#0f172a;border:1px solid var(--line);padding:2px 7px;border-radius:999px;font-size:12px;min-width:58px;text-align:center}
.control input[type=range]{width:100%;accent-color:#f59e0b;height:6px;cursor:pointer}
.range-meta{display:flex;justify-content:space-between;font-size:10px;color:#64748b;margin-top:3px}
