.tele span{display:block;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.tele strong{display:block;font-size:16px;margin-top:4px}
.tele small{font-size:10px;color:var(--muted)}
.details{font-size:12px;line-height:1.7;color:#94a3b8}
.details b{color:#e2e8f0}
