main{position:relative;display:flex;flex-direction:column;background:#0b0f13;min-width:0}
.canvas-wrap{position:relative;flex:1;min-height:560px}
canvas{display:block;width:100%;height:100%}
.hud{position:absolute;left:14px;top:12px;display:flex;gap:8px;flex-wrap:wrap;pointer-events:none}
.chip{background:rgba(10,15,22,.82);backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.12);padding:7px 10px;border-radius:999px;font-size:12px;font-weight:700}
.chip span{color:var(--muted);font-weight:600}
.legend{position:absolute;right:14px;top:12px;background:rgba(10,15,22,.82);border:1px solid rgba(255,255,255,.1);border-radius:11px;padding:9px 11px;font-size:11px;line-height:1.6;color:#cbd5e1;pointer-events:none}
.footer{padding:10px 14px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted);background:#0c1116}
.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--green);margin-right:6px;vertical-align:middle}
