<body>
<header>
  <div class="brand"><div class="logo">◈</div><div><h1>muse-wonder-1.0</h1><p>Crash Physics Laboratory</p></div></div>
  <div class="badge">Rigid-Body Sandbox • 80 px / m</div>
</header>

<div class="layout">
  <aside>
    <div class="card">
      <h2>Experiment Control</h2>
      <div class="btns">
        <button id="testBtn">▶ &nbsp;TEST</button>
        <button id="resetBtn">↺ &nbsp;Reset</button>
      </div>
      <p style="font-size:12px;line-height:1.6;color:#94a3b8;margin:11px 0 0">Test resets the scene to the current settings, then launches the car. Same settings always give the same result — no hidden randomness in physics.</p>
      <div style="display:flex;gap:8px;margin-top:10px">
        <span class="kbd">Space</span><span style="font-size:12px;color:#94a3b8">Run test</span>
        <span class="kbd">R</span><span style="font-size:12px;color:#94a3b8">Reset</span>
      </div>
    </div>

    <div class="card">
      <h2>Settings</h2>

      <div class="control">
        <label>Car speed <b><span id="v-speed">22.0</span> m/s</b></label>
        <input id="in-speed" type="range" min="5" max="45" step="0.5" value="22">
        <div class="range-meta"><span>5 m/s</span><span>45 m/s • 162 km/h</span></div>
      </div>

      <div class="control">
        <label>Wall columns <b><span id="v-cols">12</span> bricks</b></label>
        <input id="in-cols" type="range" min="4" max="24" step="1" value="12">
        <div class="range-meta"><span>4</span><span>24 wide</span></div>
      </div>

      <div class="control">
        <label>Wall rows <b><span id="v-rows">8</span> rows</b></label>
        <input id="in-rows" type="range" min="3" max="16" step="1" value="8">
        <div class="range-meta"><span>3</span><span>16 tall</span></div>
      </div>

      <div class="control">
        <label>Depth layers <b><span id="v-depth">2</span> layers</b></label>
        <input id="in-depth" type="range" min="1" max="5" step="1" value="2">
        <div class="range-meta"><span>1 thin</span><span>5 thick</span></div>
      </div>

      <div class="control" style="margin-bottom:2px">
        <label>Brick mass <b><span id="v-mass">2.5</span> kg</b></label>
        <input id="in-mass" type="range" min="0.5" max="12" step="0.1" value="2.5">
        <div class="range-meta"><span>0.5 kg</span><span>12 kg</span></div>
      </div>
    </div>

    <div class="card">
      <h2>Live Telemetry</h2>
      <div class="telemetry">
        <div class="tele"><span>Car speed</span><strong id="t-speed">0.0</strong><small>m/s</small></div>
        <div class="tele"><span>Elapsed</span><strong id="t-time">0.00</strong><small>seconds</small></div>
        <div class="tele"><span>Moving</span><strong id="t-moving">0</strong><small>bricks</small></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
        <div class="tele"><span>Impact</span><strong id="t-impact" style="font-size:13px">—</strong><small>peak impulse</small></div>
        <div class="tele"><span>Wall status</span><strong id="t-wall" style="font-size:13px">Standing</strong><small id="t-bricks">192 bricks</small></div>
      </div>
    </div>

    <div class="card">
      <h2>Fixed Parameters</h2>
      <div class="details">
        Brick <b>0.50 × 0.24 m</b> &nbsp;•&nbsp; Gravity <b>9.81 m/s²</b><br>
        Brick friction <b>μ 0.72</b> &nbsp;•&nbsp; Restitution <b>0.18</b><br>
        Car <b>1,250 kg • 4.2 × 1.45 m</b> &nbsp;•&nbsp; Ground μ <b>0.85</b><br>
        Scale <b>80 px / m</b> &nbsp;•&nbsp; Solver <b>sequential impulses, SAT</b>
      </div>
    </div>
  </aside>

  <main>
    <div class="canvas-wrap" id="wrap">
      <canvas id="cv"></canvas>
      <div class="hud">
        <div class="chip"><span>STATUS</span> &nbsp;<span class="status-dot" id="dot"></span><span id="hud-status" style="color:white">READY</span></div>
        <div class="chip"><span>CAR</span> &nbsp;<span id="hud-car" style="color:white">22.0 m/s</span></div>
        <div class="chip"><span>WALL</span> &nbsp;<span id="hud-wall" style="color:white">12 × 8 × 2</span></div>
      </div>
      <div class="legend">⬛ Car body &nbsp; 🧱 Individual bricks<br>Camera shake + dust are visual only<br>and never affect physics.</div>
    </div>
    <div class="footer">
      <span>Deterministic solver • Fixed timestep 1/120 s × substeps • Seeded dust only for visuals</span>
      <span id="foot-info">Default: 22 m/s • 12 × 8 × 2 wall • 2.5 kg bricks</span>
    </div>
  </main>
</div>

<script>
(() => {
"use strict";
// ---------- Mandatory defaults ----------
const DEFAULTS = { speed:22, cols:12, rows:8, depth:2, brickMass:2.5 };
const P = {
  brickW:0.50, brickH:0.24, gravity:9.81,
  brickFriction:0.72, restitution:0.18,
  carMass:1250, carW:4.2, carH:1.45,
  groundFriction:0.85, scale:80
};

// ---------- DOM ----------
const cv=document.getElementById('cv'), ctx=cv.getContext('2d');
const wrap=document.getElementById('wrap');
const els={
  speed:document.getElementById('in-speed'), cols:document.getElementById('in-cols'),
  rows:document.getElementById('in-rows'), depth:document.getElementById('in-depth'),
  mass:document.getElementById('in-mass'),
  vSpeed:document.getElementById('v-speed'), vCols:document.getElementById('v-cols'),
  vRows:document.getElementById('v-rows'), vDepth:document.getElementById('v-depth'), vMass:document.getElementById('v-mass'),
  tSpeed:document.getElementById('t-speed'), tTime:document.getElementById('t-time'), tMoving:document.getElementById('t-moving'),
  tImpact:document.getElementById('t-impact'), tWall:document.getElementById('t-wall'), tBricks:document.getElementById('t-bricks'),
  hudStatus:document.getElementById('hud-status'), hudCar:document.getElementById('hud-car'), hudWall:document.getElementById('hud-wall'),
  dot:document.getElementById('dot'), foot:document.getElementById('foot-info')
};
function settings(){
  return {
    speed:parseFloat(els.speed.value), cols:parseInt(els.cols.value,10),
    rows:parseInt(els.rows.value,10), depth:parseInt(els.depth.value,10),
    brickMass:parseFloat(els.mass.value)
  };
}
function syncLabels(){
  const s=settings();
  els.vSpeed.textContent=s.speed.toFixed(1); els.vCols.textContent=s.cols; els.vRows.textContent=s.rows;
  els.vDepth.textContent=s.depth; els.vMass.textContent=s.brickMass.toFixed(1);
  els.hudCar.textContent=s.speed.toFixed(1)+' m/s';
  els.hudWall.textContent=`${s.cols} × ${s.rows} × ${s.depth}`;
  els.tBricks.textContent=(s.cols*s.rows*s.depth)+' bricks';
  els.foot.textContent=`${s.speed.toFixed(1)} m/s • ${s.cols} × ${s.rows} × ${s.depth} wall • ${s.brickMass.toFixed(1)} kg bricks • ${(s.speed*3.6).toFixed(0)} km/h`;
}
['input','change'].forEach(ev=>{
  [els.speed,els.cols,els.rows,els.depth,els.mass].forEach(i=>i.addEventListener(ev,()=>{syncLabels(); if(state==='ready') buildScene(false);}));
});

// ---------- Seeded RNG (visual only) ----------
let seed=1234567;
function srand(s){seed=s>>>0}
function rnd(){seed=(seed*1664525+1013904223)>>>0; return seed/4294967296}

// ---------- Physics bodies ----------
let bricks=[], car=null, particles=[], skidMarks=[];
let state='ready'; // ready | running | settled
let elapsed=0, peakImpulse=0, hasImpacted=false, shake=0, shakeX=0, shakeY=0;
let camX=0, wheelRot=0;

function makeBody(x,y,w,h,mass,opts={}){
  const invMass=mass>0?1/mass:0;
  const inertia=mass*(w*w+h*h)/12;
  return {x,y,w,h,vx:0,vy:0,angle:0,av:0,mass,invMass,inertia,invInertia:inertia>0?1/inertia:0,
    friction:opts.friction??P.brickFriction, restitution:opts.restitution??P.restitution,
    isCar:!!opts.isCar, layer:opts.layer||0, row:opts.row||0, col:opts.col||0, sleep:0, id:opts.id||0};
}

const WALL_X=15.2; // left face of wall (m)
const CAR_START_X=3.4;

function buildScene(auto=false){
  const s=settings();
  bricks=[]; particles=[]; skidMarks=[]; elapsed=0; peakImpulse=0; hasImpacted=false; shake=0; wheelRot=0;
  srand(987654321);
  let id=1;
  // depth loop back-to-front so front layer drawn last
  for(let layer=s.depth-1; layer>=0; layer--){
    const layerOffsetX=layer*0.055; // depth appears as slight thickness offset
    for(let r=0;r<s.rows;r++){
      const y=P.brickH/2 + r*P.brickH + 0.001 + layer*0.0008;
      const stagger=(r%2===1)? P.brickW*0.5 : 0;
      for(let c=0;c<s.cols;c++){
        const x=WALL_X + P.brickW/2 + c*P.brickW + stagger + layerOffsetX;
        const b=makeBody(x,y,P.brickW,P.brickH,s.brickMass,{layer,row:r,col:c,id:id++});
        // tiny deterministic shade variation stored via id hash
        b.shade=((id*2654435761)>>>0)%100/100;
        bricks.push(b);
      }
    }
  }
  // Car as one rigid body (visual is drawn richer than box)
  car=makeBody(CAR_START_X, P.carH/2+0.08, P.carW, P.carH, P.carMass,{isCar:true,friction:0.85,restitution:0.08});
  car.crumple=0; car.pitchImpulse=0; car.wheelR=0.34;
  state='ready';
  updateTelemetry(0);
  els.hudStatus.textContent='READY'; els.dot.style.background='#22c55e';
  els.tWall.textContent='Standing'; els.tImpact.textContent='—';
}

function launch(){
  buildScene(true);
  const s=settings();
  car.vx=s.speed; // launch at configured speed (momentum = m*v)
  state='running'; elapsed=0;
  els.hudStatus.textContent='RUNNING'; els.dot.style.background='#f59e0b';
}

// ---------- Geometry helpers ----------
function axes(b){const c=Math.cos(b.angle),s=Math.sin(b.angle);return [{x:c,y:s},{x:-s,y:c}]}
function corners(b){
  const c=Math.cos(b.angle),s=Math.sin(b.angle),hw=b.w/2,hh=b.h/2;
  const pts=[];
  for(const [lx,ly] of [[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]]){
    pts.push({x:b.x+lx*c-ly*s, y:b.y+lx*s+ly*c, lx, ly});
  } return pts;
}
function projRadius(b,ax){const c=Math.abs(Math.cos(b.angle)),s=Math.abs(Math.sin(b.angle)); // approx via corners faster below
  return 0}
function satContact(a,b){
  const ax=[...axes(a),...axes(b)];
  let bestPen=Infinity,bestAxis=null;
  const dx=b.x-a.x, dy=b.y-a.y;
  for(const axis of ax){
    // project corners
    const ca=corners(a), cb=corners(b);
    let minA=Infinity,maxA=-Infinity,minB=Infinity,maxB=-Infinity;
    for(const p of ca){const d=p.x*axis.x+p.y*axis.y; if(d<minA)minA=d; if(d>maxA)maxA=d}
    for(const p of cb){const d=p.x*axis.x+p.y*axis.y; if(d<minB)minB=d; if(d>maxB)maxB=d}
    const overlap=Math.min(maxA,maxB)-Math.max(minA,minB);
    if(overlap<=0) return null;
    if(overlap<bestPen){bestPen=overlap; bestAxis={...axis}}
  }
  // orient axis from a to b
  if(bestAxis.x*dx+bestAxis.y*dy<0){bestAxis.x*=-1; bestAxis.y*=-1}
  // contact point: deepest points average (stable approximation)
  const ca=corners(a), cb=corners(b);
  let pa=ca[0], bestA=-Infinity;
  for(const p of ca){const d=p.x*bestAxis.x+p.y*bestAxis.y; if(d>bestA){bestA=d;pa=p}}
  let pb=cb[0], bestB=Infinity;
  for(const p of cb){const d=p.x*bestAxis.x+p.y*bestAxis.y; if(d<bestB){bestB=d;pb=p}}
  const cx=(pa.x+pb.x)/2, cy=(pa.y+pb.y)/2;
  return {a,b,nx:bestAxis.x,ny:bestAxis.y,pen:bestPen,x:cx,y:cy};
}

// ---------- Solver ----------
function applyImpulse(b,jx,jy,px,py){
  b.vx+=jx*b.invMass; b.vy+=jy*b.invMass;
  const rx=px-b.x, ry=py-b.y;
  b.av+=(rx*jy-ry*jx)*b.invInertia;
}
function solveContact(c,dt){
  const {a,b,nx,ny}=c;
  const rx1=c.x-a.x, ry1=c.y-a.y, rx2=c.x-b.x, ry2=c.y-b.y;
  // relative velocity at contact
  let rvx=(b.vx - b.av*ry2)-(a.vx - a.av*ry1);
  let rvy=(b.vy + b.av*rx2)-(a.vy + a.av*rx1);
  const velN=rvx*nx+rvy*ny;
  const invSum=a.invMass+b.invMass;
  if(invSum===0) return;
  // effective mass with rotation
  const rn1=rx1*ny-ry1*nx, rn2=rx2*ny-ry2*nx;
  const kn=invSum + a.invInertia*rn1*rn1 + b.invInertia*rn2*rn2;
  if(kn===0) return;
  const e = velN < -1.0 ? Math.min(a.restitution,b.restitution) : 0;
  let jn=-(1+e)*velN/kn;
  // Baumgarte positional bias handled separately; add small bias velocity
  const bias=Math.max(0,c.pen-0.0015)*0.18/dt; // gentle
  // only add bias if separating slowly? incorporate as extra impulse when penetrating
  // We'll apply bias as positional correction later, keep velocity clean.
  if(jn<0 && velN>0) jn=0; // separating - still allow friction below
  if(jn>0){
    const ix=nx*jn, iy=ny*jn;
    // apply: a gets -impulse, b gets +impulse
    applyImpulse(a,-ix,-iy,c.x,c.y);
    applyImpulse(b, ix, iy,c.x,c.y);
    if(a.isCar||b.isCar){
      if(jn>peakImpulse) peakImpulse=jn;
      if(!hasImpacted && jn>400){ hasImpacted=true; onImpact(jn); }
      const other=a.isCar?b:a;
      // car crumple proportional to impulse
      car.crumple=Math.min(0.62, car.crumple + jn*0.000012);
    }
  } else if(jn<0) jn=0;
  // Friction
  rvx=(b.vx - b.av*ry2)-(a.vx - a.av*ry1);
  rvy=(b.vy + b.av*rx2)-(a.vy + a.av*rx1);
  const tx=-ny, ty=nx;
  const velT=rvx*tx+rvy*ty;
  const rt1=rx1*ty-ry1*tx, rt2=rx2*ty-ry2*tx;
  const kt=invSum + a.invInertia*rt1*rt1 + b.invInertia*rt2*rt2;
  if(kt>0){
    let jt=-velT/kt;
    const mu=Math.sqrt(a.friction*b.friction);
    const maxF=mu*Math.max(jn, Math.abs(velN)*invSum*0.5 + 2); // allow static-ish friction even with small jn
    // better: use accumulated normal approx
    const clampVal=mu*(jn>0?jn: Math.max(0,-velN/kn)*0.8 + 1.5);
    jt=Math.max(-clampVal,Math.min(clampVal,jt));
    applyImpulse(a,-tx*jt,-ty*jt,c.x,c.y);
    applyImpulse(b, tx*jt, ty*jt,c.x,c.y);
  }
}
function positionalCorrection(c){
  const {a,b,nx,ny}=c;
  const invSum=a.invMass+b.invMass; if(!invSum) return;
  const slop=0.0015, percent=0.65;
  const corr=Math.max(c.pen-slop,0)/invSum*percent;
  a.x-=nx*corr*a.invMass; a.y-=ny*corr*a.invMass;
  b.x+=nx*corr*b.invMass; b.y+=ny*corr*b.invMass;
}

// Ground contacts as point contacts
function groundContacts(b, out){
  const cs=corners(b);
  for(const p of cs){
    if(p.y<0){
      out.push({a:GROUND,b:b,nx:0,ny:1,pen:-p.y,x:p.x,y:0,isGround:true,point:p});
      // also store corner for torque
    }
  }
}
const GROUND={x:0,y:-999,vx:0,vy:0,av:0,invMass:0,invInertia:0,friction:P.groundFriction,restitution:0.05,isCar:false};

function solveGround(c,dt){
  const b=c.b;
  const rx=c.x-b.x, ry=c.y-b.y;
  let rvx=b.vx - b.av*ry, rvy=b.vy + b.av*rx;
  const velN=rvy; // ny=1
  const rn=rx*1-ry*0;
  const kn=b.invMass + b.invInertia*rn*rn;
  if(kn===0) return;
  const e = velN < -1.2 ? b.restitution : 0;
  let jn=-(1+e)*velN/kn;
  if(jn>0){
    applyImpulse(b,0,jn,c.x,c.y);
    if(b.isCar && jn>200) {}
  }
  // friction
  rvx=b.vx - b.av*ry; rvy=b.vy + b.av*rx;
  const velT=rvx; // tangent (1,0)
  const rt=rx*0-ry*1; // rx*ty - ry*tx with t=(1,0) => -ry
  const kt=b.invMass + b.invInertia*rt*rt;
  if(kt>0){
    let jt=-velT/kt;
    const mu=b.isCar? P.groundFriction : Math.sqrt(b.friction*P.groundFriction);
    const maxF=mu*Math.max(jn,2);
    jt=Math.max(-maxF,Math.min(maxF,jt));
    applyImpulse(b,jt,0,c.x,c.y);
  }
  // positional
  const corr=Math.max(c.pen-0.001,0)*0.8;
  b.y+=corr;
  // if car: also keep from sinking, extra ground friction decel when rolling
}

function onImpact(jn){
  shake=Math.min(18, 6 + jn*0.00008);
  // dust burst at wall base - deterministic seed per impact time slice
  const wx=WALL_X, wy=0.6;
  for(let i=0;i<28;i++){
    const a=rnd()*Math.PI - 0.2, sp=0.6+rnd()*3.2;
    particles.push({x:wx+(rnd()-0.3)*0.6, y:0.15+rnd()*1.2, vx:Math.cos(a)*sp -1.5 + rnd()*1, vy:Math.abs(Math.sin(a))*sp*0.7+0.5, life:0.7+rnd()*0.9, maxLife:1.4, size:2+rnd()*5, alpha:0.55});
  }
}

function spawnDust(x,y,n,power=1){
  for(let i=0;i<n;i++){
    particles.push({x:x+(rnd()-0.5)*0.4, y:y+rnd()*0.3, vx:(rnd()-0.7)*1.6*power, vy:0.4+rnd()*1.1*power, life:0.5+rnd()*0.7, maxLife:1.1, size:1.5+rnd()*3.5, alpha:0.4});
  }
}

// ---------- Step ----------
const FIXED=1/120;
function physicsStep(dt){
  const bodies=[car,...bricks];
  // gravity + integrate forces
  for(const b of bodies){
    if(!b) continue;
    b.vy -= P.gravity*dt;
    // angular damping & linear damping (tiny, for stability)
    b.av*= (1-0.08*dt);
    // car ground rolling friction after impact: handled via contacts; add mild decel when on ground and not powered
    if(b.isCar && state==='running'){
      // before impact, maintain speed (cruise); after impact, let friction act - flag via hasImpacted
      if(!hasImpacted){
        const target=settings().speed;
        // gentle hold to target (engine) so speed readout stays true
        b.vx += (target - b.vx)*Math.min(1,dt*4);
      }
    }
  }
  // integrate positions
  for(const b of bodies){
    b.x+=b.vx*dt; b.y+=b.vy*dt; b.angle+=b.av*dt;
    // normalize angle
    if(b.angle>Math.PI) b.angle-=2*Math.PI; if(b.angle<-Math.PI) b.angle+=2*Math.PI;
    if(b.isCar){ b.angle*=0.92; b.av*=0.85; if(b.y < P.carH/2+0.08) b.y=P.carH/2+0.08; }
  }
  wheelRot += (car.vx*dt)/Math.max(0.34,0.01);

  // Broadphase via spatial hash
  const cell=0.7;
  const hash=new Map();
  function key(cx,cy){return cx+','+cy}
  bodies.forEach((b,idx)=>{
    const r=Math.max(b.w,b.h)*0.75+0.1;
    const x0=Math.floor((b.x-r)/cell), x1=Math.floor((b.x+r)/cell);
    const y0=Math.floor((b.y-r)/cell), y1=Math.floor((b.y+r)/cell);
    for(let gx=x0;gx<=x1;gx++) for(let gy=y0;gy<=y1;gy++){
      const k=key(gx,gy); if(!hash.has(k)) hash.set(k,[]); hash.get(k).push(idx);
    }
  });
  const pairSet=new Set(); const pairs=[];
  for(const arr of hash.values()){
    for(let i=0;i<arr.length;i++) for(let j=i+1;j<arr.length;j++){
      const aIdx=Math.min(arr[i],arr[j]), bIdx=Math.max(arr[i],arr[j]);
      const pk=aIdx+'_'+bIdx; if(!pairSet.has(pk)){pairSet.add(pk); pairs.push([bodies[aIdx],bodies[bIdx]]);}
    }
  }

  // Gather contacts
  let contacts=[], gContacts=[];
  for(const [a,b] of pairs){
    // quick AABB reject
    const rr=(Math.max(a.w,a.h)+Math.max(b.w,b.h))*0.85;
    const dx=b.x-a.x, dy=b.y-a.y; if(dx*dx+dy*dy>rr*rr*1.4) continue;
    const c=satContact(a,b); if(c) contacts.push(c);
  }
  for(const b of bodies) groundContacts(b,gContacts);

  // Velocity iterations
  for(let it=0;it<8;it++){
    for(const c of contacts) solveContact(c,dt);
    for(const c of gContacts) solveGround(c,dt);
  }
  // Positional correction (recompute pen approx using stored)
  for(const c of contacts) positionalCorrection(c);
  // Ground positional already done; ensure no brick below ground center
  for(const b of bricks){ if(b.y<0.05){ const cs=corners(b); let minY=Infinity; for(const p of cs) minY=Math.min(minY,p.y); if(minY<0) b.y-=minY; } }

  // Extra anti-tunneling: car front vs wall - if car overlaps wall heavily, push car back
  // (SAT already does; this is safety for high speed)
  if(car.vx>8){
    // substep already 1/120 so max move 0.375m at 45m/s < brick width - safe
  }

  // Skid marks when car decelerating hard on ground
  if(car && Math.abs(car.vx)>2 && hasImpacted){
    const decel=Math.abs((car._prevVx??car.vx)-car.vx)/Math.max(dt,0.001);
    if(decel>4 && car.y<1.0){
      skidMarks.push({x:car.x-P.carW*0.28, y:0.02, len:Math.abs(car.vx)*dt, alpha:0.35});
      if(skidMarks.length>600) skidMarks.shift();
      if(rnd()<0.25) spawnDust(car.x-P.carW/2,0.18,1,0.7);
    }
  }
  if(car) car._prevVx=car.vx;

  // Particles (visual only)
  for(let i=particles.length-1;i>=0;i--){
    const p=particles[i]; p.life-=dt; if(p.life<=0){particles.splice(i,1);continue}
    p.vy-=1.2*dt; p.vx*= (1-0.6*dt); p.x+=p.vx*dt; p.y+=p.vy*dt; if(p.y<0.05){p.y=0.05;p.vy=0}
  }
  if(shake>0) shake*=Math.pow(0.001,dt); if(shake<0.05) shake=0;
  shakeX=(rnd()-0.5)*shake; shakeY=(rnd()-0.5)*shake*0.6;
}

// ---------- Telemetry / status ----------
function movingCount(){
  let n=0; for(const b of bricks){ const sp=b.vx*b.vx+b.vy*b.vy; if(sp>0.018 || Math.abs(b.av)>0.35) n++; } return n;
}
function wallStatus(){
  let fallen=0;
  for(const b of bricks){ if(Math.abs(b.angle)>0.45 || b.y < P.brickH*0.4) fallen++; }
  // displaced check
  let displaced=0;
  // use initial wall extent: count bricks far from original x range
  for(const b of bricks){ if(b.x>WALL_X+settings().cols*P.brickW+1.2 || Math.abs(b.angle)>0.35) displaced++; }
  const ratio=displaced/Math.max(1,bricks.length);
  if(ratio>0.55) return 'Collapsed';
  if(ratio>0.22) return 'Breached';
  if(ratio>0.06) return 'Damaged';
  if(hasImpacted) return 'Held / Cracked';
  return 'Standing';
}
function updateTelemetry(dt){
  if(!car) return;
  els.tSpeed.textContent=Math.abs(car.vx).toFixed(1);
  els.tTime.textContent=elapsed.toFixed(2);
  els.tMoving.textContent=movingCount();
  if(peakImpulse>0) els.tImpact.textContent=(peakImpulse/1000).toFixed(1)+' kN·s';
  els.tWall.textContent= hasImpacted? wallStatus() : 'Standing';
}

// ---------- Rendering ----------
let W=0,H=0,DPR=1;
function resize(){
  DPR=Math.min(2,window.devicePixelRatio||1);
  const r=wrap.getBoundingClientRect();
  W=Math.max(320,r.width); H=Math.max(420,r.height);
  cv.width=Math.floor(W*DPR); cv.height=Math.floor(H*DPR);
  cv.style.width=W+'px'; cv.style.height=H+'px';
}
window.addEventListener('resize',resize);

function worldToScreen(x,y){
  const groundScreenY=H-78;
  return { x:(x-camX)*P.scale + shakeX, y:groundScreenY - y*P.scale + shakeY };
}

function drawCar(){
  const s=settings();
  const crumple=car.crumple||0;
  const pos=worldToScreen(car.x,car.y);
  const w=P.carW*P.scale, h=P.carH*P.scale;
  ctx.save(); ctx.translate(pos.x,pos.y); ctx.rotate(-car.angle*0.35); // screen y flipped, slight tilt
  // shadow
  ctx.fillStyle='rgba(0,0,0,.38)'; ctx.beginPath(); ctx.ellipse(0,h*0.48,w*0.48,10,0,0,Math.PI*2); ctx.fill();
  const frontCrush=crumple*38;
  // body
  const grad=ctx.createLinearGradient(0,-h/2,0,h/2);
  grad.addColorStop(0,'#f8fafc'); grad.addColorStop(0.45,'#cbd5e1'); grad.addColorStop(0.55,'#94a3b8'); grad.addColorStop(1,'#64748b');
  // main silhouette path (side view)
  ctx.beginPath();
  const x0=-w/2, x1=w/2-frontCrush;
  ctx.moveTo(x0+6, h*0.28);
  ctx.lineTo(x0+10, -h*0.08);
  ctx.lineTo(x0+w*0.22, -h*0.12);
  ctx.lineTo(x0+w*0.30, -h*0.42); // windshield base
  ctx.lineTo(x0+w*0.62, -h*0.46); // roof
  ctx.lineTo(x0+w*0.78, -h*0.14);
  ctx.lineTo(x1-4, -h*0.10 + crumple*10);
  ctx.lineTo(x1, h*0.10 + crumple*6);
  ctx.lineTo(x1-2, h*0.30);
  ctx.closePath();
  ctx.fillStyle=grad; ctx.fill(); ctx.strokeStyle='#334155'; ctx.lineWidth=1.2; ctx.stroke();
  // crumple folds
  if(crumple>0.03){
    ctx.strokeStyle='rgba(30,41,59,.55)'; ctx.lineWidth=1.4;
    for(let i=0;i<4;i++){ ctx.beginPath(); const fx=x1-8-i*7; ctx.moveTo(fx, -h*0.05+i*3); ctx.lineTo(fx-5, h*0.18); ctx.stroke(); }
    ctx.fillStyle='rgba(239,68,68,.22)'; ctx.fillRect(x1-16,-h*0.08,16,h*0.32);
  }
  // windows
  ctx.fillStyle='#0f2a3d';
  ctx.beginPath(); ctx.moveTo(x0+w*0.34,-h*0.38); ctx.lineTo(x0+w*0.58,-h*0.40); ctx.lineTo(x0+w*0.62,-h*0.16); ctx.lineTo(x0+w*0.38,-h*0.15); ctx.closePath(); ctx.fill();
  ctx.fillStyle='rgba(125,211,252,.28)'; ctx.fillRect(x0+w*0.36,-h*0.38,w*0.20,5);
  // door line + handle
  ctx.strokeStyle='rgba(51,65,85,.5)'; ctx.lineWidth=1; ctx.strokeRect(x0+w*0.38,-h*0.12,w*0.30,h*0.38);
  ctx.fillStyle='#334155'; ctx.fillRect(x0+w*0.60,-h*0.02,14,4);
  // lights
  ctx.fillStyle='#fef08a'; ctx.fillRect(x1-7,-h*0.02,6,8);
  ctx.fillStyle='#ef4444'; ctx.fillRect(x0+2,0,5,8);
  // stripe
  ctx.fillStyle='#f59e0b'; ctx.fillRect(x0+8,h*0.14,w*0.72,4);
  // wheels
  const wr=0.34*P.scale;
  const wy=h*0.30;
  for(const wx of [-w*0.32, w*0.32-frontCrush*0.3]){
    ctx.save(); ctx.translate(wx,wy); ctx.rotate(wheelRot * (wx>0?1:1));
    ctx.fillStyle='#111827'; ctx.beginPath(); ctx.arc(0,0,wr,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#475569'; ctx.beginPath(); ctx.arc(0,0,wr*0.55,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='#cbd5e1'; ctx.lineWidth=2;
    for(let i=0;i<5;i++){ const a=i/5*Math.PI*2; ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(Math.cos(a)*wr*0.5,Math.sin(a)*wr*0.5); ctx.stroke(); }
    ctx.fillStyle='#e2e8f0'; ctx.beginPath(); ctx.arc(0,0,4,0,Math.PI*2); ctx.fill();
    ctx.restore();
    // arch
    ctx.fillStyle='rgba(15,23,42,.22)'; ctx.beginPath(); ctx.arc(wx,wy,wr+5,Math.PI,0); ctx.fill();
  }
  // speed lines when fast and not impacted
  if(Math.abs(car.vx)>8 && !hasImpacted){
    ctx.strokeStyle='rgba(255,255,255,.16)'; ctx.lineWidth=2;
    for(let i=0;i<3;i++){ ctx.beginPath(); ctx.moveTo(x0-10-i*14, -10+i*14); ctx.lineTo(x0-55-i*10, -10+i*14); ctx.stroke(); }
  }
  ctx.restore();
  // velocity label
  ctx.fillStyle='rgba(255,255,255,.9)'; ctx.font='700 11px Inter,system-ui'; ctx.textAlign='center';
  // ctx.fillText(Math.abs(car.vx).toFixed(1)+' m/s', pos.x, pos.y-h*0.68);
}

function drawBrick(b){
  const pos=worldToScreen(b.x,b.y);
  const w=b.w*P.scale, h=b.h*P.scale;
  ctx.save(); ctx.translate(pos.x,pos.y); ctx.rotate(-b.angle);
  // layer shading: back layers darker / desaturated
  const layerDim=b.layer===0?1: (b.layer===1?0.82:0.68 - b.layer*0.02);
  const v=(b.shade||0)*14;
  const r=Math.floor((176+v)*layerDim), g=Math.floor((72+v*0.4)*layerDim), bl=Math.floor((52+v*0.3)*layerDim);
  ctx.fillStyle=`rgb(${r},${g},${bl})`;
  const rad=3;
  ctx.beginPath(); ctx.roundRect(-w/2,-h/2,w,h,rad); ctx.fill();
  // top highlight & bottom shade for depth
  ctx.fillStyle='rgba(255,255,255,.16)'; ctx.fillRect(-w/2+2,-h/2+2,w-4,4);
  ctx.fillStyle='rgba(0,0,0,.18)'; ctx.fillRect(-w/2+2,h/2-5,w-4,3);
  ctx.strokeStyle='rgba(60,20,12,.65)'; ctx.lineWidth=1; ctx.stroke();
  // brick texture: 2 small pits deterministic
  ctx.fillStyle='rgba(0,0,0,.14)';
  const s1=((b.id*37)%40)/40, s2=((b.id*91)%40)/40;
  ctx.fillRect(-w/2+6+s1*w*0.5, -2, 5,2); ctx.fillRect(-w/2+10+s2*w*0.4, 3,4,2);
  // front layer mortar edge
  if(b.layer===0){ ctx.strokeStyle='rgba(255,220,180,.12)'; ctx.strokeRect(-w/2+1,-h/2+1,w-2,h-2); }
  ctx.restore();
}

function draw(){
  ctx.setTransform(DPR,0,0,DPR,0,0);
  // sky / lab background
  const sky=ctx.createLinearGradient(0,0,0,H);
  sky.addColorStop(0,'#0e1a26'); sky.addColorStop(0.55,'#152736'); sky.addColorStop(0.56,'#1a2e22'); sky.addColorStop(1,'#111827');
  ctx.fillStyle=sky; ctx.fillRect(0,0,W,H);
  // distant wall panels / grid
  ctx.strokeStyle='rgba(255,255,255,.055)'; ctx.lineWidth=1;
  const groundY=H-78;
  for(let gx=0;gx<W;gx+=44){ ctx.beginPath(); ctx.moveTo(gx,0); ctx.lineTo(gx,groundY); ctx.stroke(); }
  for(let gy=18;gy<groundY;gy+=36){ ctx.beginPath(); ctx.moveTo(0,gy); ctx.lineTo(W,gy); ctx.stroke(); }
  // back wall sign
  ctx.fillStyle='rgba(255,255,255,.06)'; ctx.font='800 42px Inter,system-ui'; ctx.textAlign='left';
  ctx.fillText('CRASH TEST  •  BAY 01', 22, 52);
  ctx.font='600 11px Inter,system-ui'; ctx.fillStyle='rgba(255,255,255,.28)';
  ctx.fillText('RIGID-BODY PHYSICS  —  EVERY BRICK IS SIMULATED', 24, 70);

  // camera: keep car + wall in view
  const targetCamX = (()=> {
    // world width visible
    const visW=W/P.scale;
    const wallRight=WALL_X + settings().cols*P.brickW + 1.5;
    const left=0.3;
    if(visW >= wallRight-left+1) return left - 0.6;
    // follow car but keep wall ahead visible when close
    const desired = car ? car.x - visW*0.28 : 0;
    const maxCam = wallRight - visW + 0.8;
    return Math.max(left-0.6, Math.min(desired, maxCam));
  })();
  camX += (targetCamX-camX)*0.08;
  if(state==='ready') camX=targetCamX; // snap on reset for clean framing

  // ground
  ctx.fillStyle='#232a33'; ctx.fillRect(0,groundY,W,H-groundY);
  ctx.fillStyle='#2f3a46'; ctx.fillRect(0,groundY,W,6);
  ctx.fillStyle='#f59e0b'; ctx.fillRect(0,groundY+6,W,2);
  // track surface
  ctx.fillStyle='#1c232d'; ctx.fillRect(0,groundY+8,W,44);
  // meter ticks
  ctx.font='600 10px Inter,system-ui'; ctx.textAlign='center';
  const startM=Math.floor(camX)-1, endM=Math.ceil(camX+W/P.scale)+1;
  for(let m=startM;m<=endM;m++){
    const sx=(m-camX)*P.scale;
    ctx.fillStyle='rgba(255,255,255,.22)'; ctx.fillRect(sx,groundY+8,1,10);
    if(m%2===0){ ctx.fillStyle='rgba(255,255,255,.38)'; ctx.fillText(m+' m', sx, groundY+32); }
    // dashed centre line
    if(m%1===0){ ctx.fillStyle='rgba(245,158,11,.28)'; ctx.fillRect(sx,groundY+46,22,3); }
  }
  // skid marks
  for(const sm of skidMarks){
    const p=worldToScreen(sm.x,0.03);
    ctx.fillStyle=`rgba(10,10,10,${sm.alpha})`; ctx.fillRect(p.x, groundY+10, Math.max(6,sm.len*P.scale), 5);
    ctx.fillRect(p.x, groundY+22, Math.max(6,sm.len*P.scale), 4);
  }
  // start line & wall zone
  const startPos=worldToScreen(CAR_START_X-P.carW/2,0);
  ctx.fillStyle='rgba(34,197,94,.85)'; ctx.fillRect(startPos.x,groundY-2,3,14);
  ctx.fillStyle='white'; ctx.font='700 10px Inter,system-ui'; ctx.textAlign='left'; ctx.fillText('START', startPos.x+6, groundY-6);
  const wallPos=worldToScreen(WALL_X,0);
  ctx.fillStyle='rgba(239,68,68,.9)'; ctx.fillRect(wallPos.x-2,groundY-2,3,14);
  ctx.fillText('WALL', wallPos.x+5, groundY-6);
  // distance marker car->wall
  if(car && !hasImpacted){
    const cp=worldToScreen(car.x+P.carW/2,0); const wp=worldToScreen(WALL_X,0);
    const dist=Math.max(0,WALL_X-(car.x+P.carW/2));
    ctx.strokeStyle='rgba(255,255,255,.28)'; ctx.setLineDash([5,5]); ctx.beginPath(); ctx.moveTo(cp.x,groundY-18); ctx.lineTo(wp.x,groundY-18); ctx.stroke(); ctx.setLineDash([]);
    ctx.fillStyle='rgba(255,255,255,.85)'; ctx.font='700 11px Inter,system-ui'; ctx.textAlign='center';
    ctx.fillText(dist.toFixed(1)+' m to wall', (cp.x+wp.x)/2, groundY-24);
    // impact speed arrow
    ctx.fillStyle='#fbbf24'; ctx.font='800 12px Inter,system-ui';
    ctx.fillText('→  '+Math.abs(car.vx).toFixed(1)+' m/s  ('+(Math.abs(car.vx)*3.6).toFixed(0)+' km/h)', cp.x+30, groundY-42);
  }

  // bricks back-to-front: draw higher layer first (already sorted), but ensure front last
  const sorted=[...bricks].sort((a,b)=>b.layer-a.layer);
  for(const b of sorted) drawBrick(b);

  // car on top
  if(car) drawCar();

  // dust particles
  for(const p of particles){
    const sp=worldToScreen(p.x,p.y);
    const a=Math.max(0,p.life/p.maxLife)*p.alpha;
    ctx.fillStyle=`rgba(210,190,160,${a})`;
    ctx.beginPath(); ctx.arc(sp.x,sp.y,p.size*(1.6-p.life/p.maxLife),0,Math.PI*2); ctx.fill();
  }

  // impact flash vignette handled via shake only

  // settled banner
  if(state==='settled'){
    ctx.fillStyle='rgba(8,12,18,.78)'; ctx.strokeStyle='rgba(255,255,255,.14)';
    const bw=340,bh=62,bx=(W-bw)/2,by=78;
    ctx.beginPath(); ctx.roundRect(bx,by,bw,bh,12); ctx.fill(); ctx.stroke();
    ctx.fillStyle='white'; ctx.font='800 15px Inter,system-ui'; ctx.textAlign='center';
    ctx.fillText('Test complete — debris settled', W/2, by+26);
    ctx.fillStyle='#94a3b8'; ctx.font='600 12px Inter,system-ui';
    ctx.fillText(`${wallStatus()}  •  ${elapsed.toFixed(2)}s  •  Peak ${(peakImpulse/1000).toFixed(1)} kN·s  —  Press TEST to run again`, W/2, by+46);
  }
}

// ---------- Main loop ----------
let last=performance.now(), acc=0, settleTimer=0;
function frame(now){
  requestAnimationFrame(frame);
  let dt=(now-last)/1000; last=now;
  if(dt>0.05) dt=0.05;
  if(state==='running'){
    acc+=dt;
    let steps=0;
    while(acc>=FIXED && steps<10){ physicsStep(FIXED); elapsed+=FIXED; acc-=FIXED; steps++; }
    // occasional dust from rolling bricks
    if(hasImpacted && rnd()<0.18){
      const fast=bricks.find(b=>Math.abs(b.vx)>2.2);
      if(fast) spawnDust(fast.x, fast.y,1,0.8);
    }
    updateTelemetry();
    // settle detection
    const mv=movingCount();
    const carSlow=Math.abs(car.vx)<0.12 && Math.abs(car.vy)<0.2;
    if(hasImpacted && mv<=2 && carSlow){ settleTimer+=dt; if(settleTimer>0.9){ state='settled'; els.hudStatus.textContent='SETTLED'; els.dot.style.background='#38bdf8'; } }
    else if(elapsed>0.2 && !hasImpacted && car.x+P.carW/2 > WALL_X+settings().cols*P.brickW+4){
      // missed? shouldn't happen
    } else settleTimer=0;
    if(elapsed>18){ state='settled'; els.hudStatus.textContent='SETTLED'; els.dot.style.background='#38bdf8'; }
    // car stopped far after wall = also settle check without impact flag if it passed through gaps
    if(elapsed>1 && Math.abs(car.vx)<0.08 && movingCount()===0 && settleTimer>0.5){}
  }
  draw();
}
document.getElementById('testBtn').addEventListener('click',launch);
document.getElementById('resetBtn').addEventListener('click',()=>buildScene(false));
window.addEventListener('keydown',e=>{
  if(e.code==='Space'){ e.preventDefault(); launch(); }
  if(e.key==='r'||e.key==='R'){ buildScene(false); }
});

// init
resize(); syncLabels(); buildScene(false);
// keep canvas height synced after layout
setTimeout(resize,50);
requestAnimationFrame(frame);
})();
